47:   processor: string | null;
48:   merchant_id: string | null;
49:   bank_account_id: string | null;
50:   gross_cents: Cents; // actual signed payment, NOT invoice total
51:   reported_net_cents: Cents | null; // null is not zero
52:   reported_fee_cents: Cents | null;
53:   fee_mode: "NETTED" | "SEPARATE_INVOICE" | "GROSS_SETTLED" | "UNKNOWN";
54:   reference: string | null;
55:   gl_account_code: string | null;
56:   payment_status: "SUCCESS" | "PENDING" | "FAILED" | "VOID" | "UNKNOWN";
