132: export type SearchStatus = "COMPLETE" | "AMBIGUOUS" | "CANDIDATE_CAP" | "CARDINALITY_CAP" | "TIMEOUT" | "UNSUPPORTED";
133: export interface ReconciliationGroup {
134:   id: string;
135:   company_id: string;
136:   bank_account_id: string;
137:   clearing_account_ids: string[];
