139:   currency: Currency;
140:   st_ids: string[];
141:   qb_ids: string[];
142:   bank_ids: string[];
143:   gross_cents: Cents; // sum of POSITIVE original receipts; excludes signed refunds/corrections
144:   refunds_cents: Cents; // magnitude, nonnegative
145:   fees_cents: Cents;
146:   holds_cents: Cents;
147:   releases_cents: Cents;
148:   external_receipts_cents: Cents;
149:   other_adjustments_cents: Cents; // signed
150:   bank_cents: Cents;
151:   unexplained_cents: Cents;
152:   ledger_residual_cents: Cents;
