154:   matching_scope: "ACTIVITY_BRIDGE" | "VERIFIED_THREE_WAY";
155:   search_status: SearchStatus;
156:   diagnoses: Array<{ cause: Cause; evidence_level: EvidenceLevel; score: number; evidence_refs: string[]; missing_evidence: string[] }>;
157:   aje_state: "INELIGIBLE" | "DRAFT" | "APPROVED" | "EXPORTED" | "VERIFIED_IN_QB";
158:   source_version_hash: string;
