## FILE src/engine/calendar.ts SHA256 fa5d3ca205e1330ee3ad66b2b10d95a7f38acfe747bdb7ea5e2b626fa74b34b8
1: import type { CalendarConfig } from '../contracts/engine';
2: export function validISODate(s: string): boolean {
3:   if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
4:   const d = new Date(`${s}T00:00:00Z`);
5:   return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
6: }
7: function iso(d: Date): string { return d.toISOString().slice(0, 10); }
8: function nth(y: number, m: number, weekday: number, n: number): string {
9:   const d = new Date(Date.UTC(y, m, 1)); d.setUTCDate(1 + (weekday - d.getUTCDay() + 7) % 7 + (n - 1) * 7); return iso(d);
10: }
11: function last(y: number, m: number, weekday: number): string {
12:   const d = new Date(Date.UTC(y, m + 1, 0)); d.setUTCDate(d.getUTCDate() - (d.getUTCDay() - weekday + 7) % 7); return iso(d);
13: }
14: /** Federal Reserve settlement convention: Sunday fixed holidays observed Monday;
15:  * Saturday holidays are not moved to Friday. Explicit provider overrides replace defaults. */
16: export function settlementHolidays(year: number): string[] {
17:   const fixed = [[0, 1], [5, 19], [6, 4], [10, 11], [11, 25]].map(([m, day]) => {
18:     const d = new Date(Date.UTC(year, m!, day!)); if (d.getUTCDay() === 0) d.setUTCDate(d.getUTCDate() + 1); return iso(d);
19:   });
20:   return [...fixed, nth(year, 0, 1, 3), nth(year, 1, 1, 3), last(year, 4, 1), nth(year, 8, 1, 1), nth(year, 9, 1, 2), nth(year, 10, 4, 4)].sort();
21: }
22: export function businessAdd(date: string, days: number, calendar: CalendarConfig = {}): string {
23:   if (!validISODate(date) || !Number.isInteger(days) || Math.abs(days) > 3660) throw new Error('Invalid business date/offset');
24:   const d = new Date(`${date}T00:00:00Z`); const step = days < 0 ? -1 : 1; let remaining = Math.abs(days);
25:   const holidays = new Set(calendar.holidays ?? [...settlementHolidays(d.getUTCFullYear() - 1), ...settlementHolidays(d.getUTCFullYear()), ...settlementHolidays(d.getUTCFullYear() + 1)]);
26:   while (remaining) { d.setUTCDate(d.getUTCDate() + step); if (d.getUTCDay() !== 0 && d.getUTCDay() !== 6 && !holidays.has(iso(d))) remaining--; }
27:   return iso(d);
28: }
29: export function inWindow(anchor: string, observed: string, calendar: CalendarConfig = {}): boolean {
30:   return observed >= businessAdd(anchor, -1, calendar) && observed <= businessAdd(anchor, 5, calendar);
31: }


## FILE src/engine/conservation.ts SHA256 d8bde32aed208031c5935009fa0443c4db476b71d3eb99034a12e15e873de0b2
1: import type { AllocationClaim, AtomControl, SourceControls, AccountControl, ReconcileInput } from '../contracts/engine';
2: import type { Normalized } from './normalize';
3: import { sumCents } from './money';
4: export function buildControls(input:ReconcileInput,ctx:Normalized,allocations:AllocationClaim[]):SourceControls{
5:   const map=new Map<string,number>();for(const a of allocations)map.set(a.atom_id,sumCents([map.get(a.atom_id)??0,a.signed_allocated_cents]));
6:   const atoms:AtomControl[]=[...ctx.st.map(r=>({atom_id:r.id,source:'ST' as const,source_cents:r.gross_cents})),...ctx.qb.map(r=>({atom_id:r.id,source:'QB' as const,source_cents:r.signed_cents})),...ctx.bank.map(r=>({atom_id:r.id,source:'BANK' as const,source_cents:r.signed_cents}))].map(a=>({...a,allocated_cents:map.get(a.atom_id)??0,residual_cents:a.source_cents-(map.get(a.atom_id)??0),excluded_reason:null}));
7:   const conservation_ok=atoms.every(a=>Math.abs(a.allocated_cents)<=Math.abs(a.source_cents)&&(a.allocated_cents===0||Math.sign(a.allocated_cents)===Math.sign(a.source_cents))&&Number.isSafeInteger(a.residual_cents));
8:   if(!conservation_ok)throw new Error('SOURCE_BUDGET_CONSERVATION_FAILED');
9:   const accounts:AccountControl[]=[];const accountNames=[...new Set(ctx.qb.map(r=>r.account_full_name))].sort();
10:   for(const name of accountNames){const rows=ctx.qb.filter(r=>r.account_full_name===name);const id=rows[0]!.account_id??name;
11:     const debit=sumCents(rows.map(r=>r.debit_cents)),credit=sumCents(rows.map(r=>r.credit_cents));
12:     const candidates=input.manifests.filter(m=>['QBO','QBD'].includes(m.source_system)).flatMap(m=>m.account_balances.filter(a=>a.account_full_name===name));
13:     const distinct=[...new Map(candidates.map(a=>[JSON.stringify(a),a])).values()];const meta=distinct.length===1?distinct[0]:undefined;
14:     const opening=meta?.opening_debit_balance_cents??null,closing=meta?.closing_debit_balance_cents??null;const calculated=opening===null?null:sumCents([opening,debit,-credit]);
15:     accounts.push({account_id:id,account_full_name:name,debit_cents:debit,credit_cents:credit,activity_cents:debit-credit,opening_cents:opening,closing_cents:closing,calculated_closing_cents:calculated,coverage_confirmed:meta?.coverage_confirmed??false,status:calculated!==null&&closing!==null?(calculated===closing?(meta?.coverage_confirmed?'VERIFIED':'ACTIVITY_ONLY'):'MISMATCH'):'ACTIVITY_ONLY'});
16:   }
