1: import type { ReconcileInput, ReconcileResult } from '../contracts/engine';
2: export interface WorkerResult { result: ReconcileResult; duration_ms: number }
3: /** A fresh worker per run isolates cancelled or stale runs. No main-thread fallback. */
4: export function runReconciliation(input: ReconcileInput, signal?: AbortSignal): Promise<WorkerResult> {
5:   return new Promise((resolve, reject) => {
6:     if (signal?.aborted) { reject(new Error('Run cancelled.')); return; }
7:     const worker = new Worker(new URL('./reconcile.worker.ts', import.meta.url), { type: 'module' });
8:     const id = crypto.randomUUID();
9:     let finished = false;
10:     const close = () => { if (finished) return; finished = true; clearTimeout(timer); signal?.removeEventListener('abort', abort); worker.terminate(); };
11:     const abort = () => { close(); reject(new Error('Run cancelled. No results were accepted.')); };
12:     // Safety watchdog is NOT the <500ms performance acceptance target.
13:     const timer = setTimeout(() => { close(); reject(new Error('Processing limit reached. Narrow the file scope; the search was not completed.')); }, 10_000);
14:     signal?.addEventListener('abort', abort, { once: true });
15:     worker.onmessage = (event: MessageEvent) => {
16:       if (event.data.id !== id || finished) return;
17:       close();
18:       if (event.data.ok) resolve({ result: event.data.result as ReconcileResult, duration_ms: event.data.duration_ms });
19:       else reject(new Error('Reconciliation stopped. Review validation errors.'));
20:     };
21:     worker.onerror = () => { close(); reject(new Error('Local worker unavailable. No data was sent to a server.')); };
22:     worker.postMessage({ id, input });
23:   });
24: }


